import{_ as s,C as a,o as r,c as l,j as t,a as o,E as i,a2 as h}from"./chunks/framework.C0pL2NcE.js";const v=JSON.parse('{"title":"7. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),d={name:"gdd/changelog.md"},c={id:"latest-main",tabindex:"-1"};function u(g,e,w,m,p,f){const n=a("Badge");return r(),l("div",null,[e[3]||(e[3]=t("h1",{id:"_7-changelog",tabindex:"-1"},[o("7. Changelog "),t("a",{class:"header-anchor",href:"#_7-changelog","aria-label":'Permalink to "7. Changelog"'},"​")],-1)),e[4]||(e[4]=t("p",null,[o("Every published version stays playable at its own URL. The "),t("a",{href:"https://tuandds.github.io/colony-flow-sand/",target:"_blank",rel:"noreferrer"},"landing page"),o(" lists them all.")],-1)),t("h2",c,[e[0]||(e[0]=o("latest (main) ",-1)),i(n,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),e[5]||(e[5]=h('<ul><li><strong>Levels 1–10 updated</strong> from a new Level Bank export (colony-flow-levels (7).json): new pictures of the same ten subjects, made in the Level Editor from images (5,884 to 15,027 grains); levels 1, 2, 6 and 7 use 3 nest columns; new hand-set nests on levels 5–8; level 9 (octopus) has a 4th colour, a pink mouth. Levels 11–20 are unchanged. Not checked with the test bot.</li><li><strong>Level Editor: grain counts in the image generator:</strong> the &quot;Tạo tranh cát từ ảnh&quot; popup shows two labelled counts: <strong>Tranh mới</strong> (the picture made from the image: blocks, grains, frame size) and <strong>Tranh hiện tại</strong> (the level&#39;s picture now, counted as in the Sand Editor header), to compare before pressing &quot;Dùng tranh này&quot;.</li><li><strong>Ten new first levels:</strong> levels 1–10 are new pictures drawn by the <a href="./level-design">level design rules</a>: strawberry, mushroom, donut, bee, tulips in a pot, whale, chick, clownfish, octopus and a ladybug on a leaf, each one subject on the empty frame with no outline (every colour is part of the picture), in 3 colours (4 on levels 5 and 10), growing in two runs of five from about 6,000 to 15,000 grains. The game builds their nests. The earlier ten move to levels 11–20 unchanged; the marketing reels still show them. The Level Editor lists all 20 in the game&#39;s order (a Level Bank saved before gets the new ones added once, and its Game chapter is put in the game&#39;s order), and its saves keep levels that exist only in <code>level-edits.json</code>. Not checked with the test bot.</li><li><strong>GDD: Level design rules:</strong> a new chapter (5) with rules for drawing, colouring and building levels, adapted from the voxel level guide and colour harmony (complementary, split-complementary, triadic): the 30 colours on the colour wheel, palette and contrast rules (CIEDE2000), minimum sizes, release order, nests, difficulty, Frozen, a checklist, and the current levels measured against them. Roadmap and Changelog are now chapters 6 and 7.</li><li><strong>36 conveyor slots:</strong> the belt holds 36 blocks (was 30), about 46 px apart (was 55), so it takes longer to fill up. Not checked with the test bot.</li><li><strong>Level set updated</strong> from a new Level Bank export (colony-flow-levels (6).json): level_1 in 3 colours (the cherries&#39; light pink shine is gone), level_2 in 3 colours (the cherry on top is yellow, no more red), and new hand-set nests for level_5. The other levels are unchanged. Not checked with the test bot.</li><li><strong>Nest columns close up:</strong> when a column runs out of nests, the columns left slide together and stay centred on the screen, at the same spacing (172 px with 4 columns), instead of leaving a gap. Not checked with the test bot.</li><li><strong>level_6 without Frozen:</strong> its ice square is removed; no level has a Frozen area now (the obstacle and its Level Editor tool stay).</li><li><strong>30 standard colours:</strong> the game&#39;s colours are now the 30 colours of Cube Blast&#39;s voxel materials (Voxel.shader, VoxelMaterials.json), each the middle tone of its material&#39;s shading ramp; the old colours are gone. Every level moved onto them, each colour to the nearest standard one (CIEDE2000), never two onto one, so blocks and nests are unchanged: ink → black, forest → olivegreen, red → red, pink → pink, white → white, yellow → yellow, lemon → lightyellow, lime and chartreuse → yellowgreen, sky → cyan, royal → navy, orange → lightorange, blush → lightpink. The Level Editor&#39;s Colour Bank is the 30 colours (a saved Bank is replaced once), and older pictures are moved onto them when opened or played. See <a href="./../guide/level-editor#_1-colour-bank">Colour Bank</a>.</li><li><strong>No more holes in the pictures:</strong> tiny empty pockets inside the pictures, where the frame&#39;s light blue showed through as pale dots (for example along the edge of level_6&#39;s blue sail against the sky), are filled with the colour round them: level_3 106 grains, level_5 30, level_6 25, level_10 28. In levels 3 and 10 a colour makes a block more, so a hand-set nest of it is a block bigger. <strong>Level Editor:</strong> the image converter now fills these itself: an empty pocket of 6 grains or fewer that doesn&#39;t reach the picture&#39;s edge takes the colour most common round it. Background removal made them: soft edge pixels between two colours can be close to the background colour.</li><li><strong>No more colour specks in the pictures:</strong> stray grains of a third colour along the borders between two colours (for example pink grains between the white and dark of level_9&#39;s house) take the colour round them, in every level: level_2 10 grains, level_3 141, level_4 91, level_5 135, level_6 17, level_7 157, level_8 20, level_9 93, level_10 317 (level_1 had none). Where a colour now makes a block more or less (levels 3, 5, 7 and 10), a hand-set nest of that colour is a block bigger or smaller, so the nests still hold exactly the picture&#39;s blocks (level_4&#39;s nests are built by the game). Not checked with the test bot. <strong>Level Editor:</strong> the image converter now cleans these up itself: a patch of a colour of 6 grains or fewer (counting diagonal neighbours, so thin diagonal lines stay) takes the colour most common round it. They came from the image&#39;s soft edges: between white and a dark colour the edge pixels are a middle grey, nearest to a third colour.</li><li><strong>Frame exactly as the art:</strong> the dark stroke drawn over the sand along the inside of the frame (img/frame_stroke.png) is gone, so the frame shows just as the art is drawn.</li><li><strong>Frozen redrawn as clear ice:</strong> the picture under it shows through tinted blue (stronger than the pale frosted look), cracked into pale cells, with a white glow along the inside of its edge and a soft glow round its outside; no hard white rim.</li><li><strong>New frame and conveyor art:</strong> the frame and the conveyor are the new art as delivered (the frame&#39;s lilac top band is the art&#39;s own; the shading added to it before is gone). The conveyor comes with its own hollow in the wood, so the one added before is gone; its band is drawn the same size and place as before.</li><li><strong>Level Editor: Frozen areas:</strong> a ❄️ tool (<code>F</code>) and a Frozen section in the Sand Editor. Drag on the picture to draw an area, drag inside it to move it, drag its corners to resize it (Shift keeps it square or round); pick one to set its shape (square or round), its count and its size in cells, or delete it. <strong>＋ Thêm vùng</strong> adds a 5 × 5 cell square in the middle. Undo covers it; the playtest plays it. See the <a href="./../guide/level-editor">Level Editor guide</a>.</li><li><strong>Frozen looks like frosted glass:</strong> the ice no longer hides the picture: the sand under it shows through blurred and washed pale blue, so its pattern and colours can still be made out.</li><li><strong>New obstacle: Frozen:</strong> a square or round patch of the picture lies under a sheet of ice with a number on it. The sand under it cannot be swept or come loose, and falling sand piles up on it. Each nest removed counts the number down by 1; at 0 the ice shatters (shards fly out and fall) and the sand under it can be swept like any other. level_6 has one, a square on the sail counting from 20. The Level Editor keeps a level&#39;s frozen areas and outlines them on the Sand Editor. See <a href="./core-gameplay#obstacle-frozen">Core gameplay</a>. Not checked with the test bot.</li><li><strong>Blocks come out of the gate:</strong> a finished block now waits in, and drops onto the belt from, the opening of the gate at the bottom of the frame (it used to appear at the end of the funnel&#39;s spout, inside the frame).</li><li><strong>Level Editor: the iPhone playtest stays in the window:</strong> it is drawn narrower when the window is too short for its 9:16 screen, and is kept inside the window when it opens, is moved or resized, or the window is resized (it used to run off the bottom of shorter windows).</li><li><strong>Game levels always named level_x:</strong> the game and the Level Editor name the game&#39;s ten levels <code>level_1</code> to <code>level_10</code> by their place in the game, whatever name a copy in the Level Bank or an imported file carries (an export with an old name, such as &quot;Hot Air Balloon&quot;, still shows as <code>level_6</code>).</li><li><strong>level_6 replaced:</strong> a new picture (a sailboat on the waves, with seagulls and a sun, four colours) from the Level Editor, with hand-set nests (49 nests over 4 columns). Not checked with the test bot.</li><li><strong>New frame and conveyor art:</strong> the picture frame is the new art with its own spout and gate (the separate gate image is gone). Its inside still fits the same 824 × 776 sand area: the sand starts under the art&#39;s grey top band, and its top edge rounds with the light blue&#39;s corners there (not the white rim&#39;s); the bottom corners round much less than before (pictures keep more sand there), and the funnel is a little longer (the hole is 183 px under the board, was 159). The art is drawn about 3 % taller than wide, and the boosters and the x2 button moved up 23 px to make room. The grey band along the top of the inside is shaded as a wall under the raised white rim: light just under the rim, darker down to the crease where it meets the light blue (it was one flat colour); the shading wraps round the top corners and fades out down the sides, so the frame reads as a 3D tray. A dark stroke (the art&#39;s outline colour, about 3 px) runs along the inside&#39;s edge, from under the grey band down the sides and the funnel to the spout; it is drawn over the sand (img/frame_stroke.png), so it shows even where a picture fills the frame, and covers the outermost sand there. The conveyor is the new art, laid out as in the Sugar Drop layout: just under the gate with a small gap, slimmer (round ends of radius 50, was 62; a narrower band) and a little longer (674 px straight, was 608), centred 88 px lower; the nests moved down with it (64 px), so less of the third row shows. The conveyor sits in the wood: its thin outer lip is redrawn as a wider wall all round (about 8 px), dark wood at the top as if in shadow and light at the bottom as if lit, so the belt looks set into a hollow in the table. The holder under each slot is the new art (a dark slate square, 22 px, solid; it was half-clear and 30 px). Recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>Level Editor: the sand frame fills its panel:</strong> the frame is as wide as the Sand Editor panel, and its size changes only when the panel or the window is resized. It used to change size unexpectedly while you worked: a scrollbar coming or going in the panel resized it (the panels now keep room for their scrollbar).</li><li><strong>Level Editor: move a picture in the frame:</strong> buttons ← ↑ ↓ → beside undo in the Sand Editor move the whole picture 0.2 cell at a time (five presses make one cell, 8 grains). Sand pushed past the frame&#39;s edge or into its rounded corners is cut off (a toast says how many grains, and the nests must be generated again), so pictures that fill the frame move too; a move that cuts nothing keeps the nests. The recorded win is dropped.</li><li><strong>Gameplay-only reels:</strong> the marketing reels are now five of 30 s (<code>?demo=drops30</code>, <code>sweeps30</code>, <code>zigzag30</code>, <code>diagonals30</code>, <code>rises30</code>) and two of 60 s (<code>mix60</code>, <code>tour60</code>). They show gameplay only, at x2 from the start, with no boosters; they differ in their levels and in their mix of strokes (each reel lists the kinds its hand takes in turn). The hand waits a little sooner while the conveyor is busy. The booster reels are gone. See <a href="./../guide/demo-videos">Demo Videos</a>.</li><li><strong>Self-playing marketing reels:</strong> seven reels play the game by themselves for marketing clips, four of 30 s (<code>?demo=play30</code>, <code>speed30</code>, <code>fan30</code>, <code>boost30</code>) and three of 60 s (<code>play60</code>, <code>boosters60</code>, <code>montage60</code>). A hand swipes the sand (down from the middle to the bottom, diagonally down, up from the bottom, along the bottom both ways, zigzags; every stroke reaches the bottom of the sand under it, so the freed sand runs out at once) and taps the boosters, slowly enough that the conveyor never fills (no Out of Space, no win). Each reel is short shots of different levels; the next level slides in from the right and pushes the last one out. The last 3 s are an end card: the last frame blurs and dims, the Sugar Drop logo pops in and a green <strong>PLAY NOW</strong> button keeps growing and shrinking. See <a href="./../guide/demo-videos">Demo Videos</a>. Normal play is unchanged; the test bot also no longer waits on sand that has come to rest loose on the board.</li><li><strong>Shuffle animation:</strong> using Shuffle holds the game, the nests pulse for 0.5 s, then they slide to their new places (about 0.5 s) and play goes on.</li><li><strong>Level set updated</strong> from a new Level Bank export: new hand-set nests for Cupcake, Goldfish, Hot Air Balloon, Cactus Pot, Garden Snail, Rocket and Penguin; new pictures for Hot Air Balloon and Cactus Pot. The game plays the levels in the Level Bank&#39;s order (Cherries, Ice Cream, Cupcake, Little Owl, Goldfish, Hot Air Balloon, Cactus Pot, Garden Snail, Rocket, Penguin): Goldfish moves from level 3 to level 5 (<code>GAME_ORDER</code> in <code>src/game/levels.ts</code>; the levels keep their ids). The levels are renamed <code>level_1</code> to <code>level_10</code> in that order. Not checked with the test bot.</li><li><strong>New level set:</strong> all ten levels are the new pictures from the Level Bank export (its &quot;Game&quot; chapter, <code>builtin-0</code> to <code>builtin-9</code>), whole-frame pictures from the Level Editor with nests the game builds. The bank&#39;s three work-in-progress levels are not in the game. Not checked with the test bot.</li><li><strong>Ants like Colony Flow&#39;s:</strong> glossy, with a white shine, instead of matte; black ants stay black but are lit enough that their shape and shine show (they were a flat black shape); seen a little more from the side, bobbing as they walk, with Colony Flow&#39;s soft shadow under each (a dark ellipse along the ant, a little below and right of it, over the belt and the nests; the old one was too faint to see); the 3D layer (ants and blocks) is drawn at full resolution (it was 75 %), so they are sharper.</li><li><strong>Pictures play exactly as drawn:</strong> the game no longer adds, removes or recolours grains to make each colour a whole number of blocks (that had changed pictures, for example Cherries&#39; leaf lost its vein). Instead a colour&#39;s leftover grains (fewer than 64) make its last block when its last grain goes down the hole, so each colour makes its grains ÷ 64 blocks, rounded up; nests are counted the same way. The game now shows every picture grain for grain as the Level Editor does (only the frame&#39;s rounded corners are cut, in both). Recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>One sand pile from board to hole:</strong> the funnel is no longer a separate pile of 6 px clumps under an invisible floor: the board&#39;s grains fall straight on into it, slide down its curved sides (and off the curved rim of the board&#39;s bottom corners), pile up and go down the hole at the gate, 540 grains a second while no block waits in it. A full funnel backs the sand up into the board. It keeps the &quot;first down, first out&quot; rule: grains are numbered as they come down into the funnel, move oldest first, and the hole takes its oldest grains first, so sand comes out within about 3 blocks of the order it came down in. Recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>Sugar Drop layout:</strong> laid out like the Sugar Drop prototype screen: a white &quot;Level N&quot; with a dark outline, smaller boosters (126 px, were 150) in a row under it with a small x2 button beside them, and a slightly smaller picture frame (inside 824 × 776 px, was 870 × 820; grains about 4.4 px, were 4.6), its funnel ending in the kit&#39;s gate on the conveyor. The conveyor and the nests stay where they were. Recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>Nest boxes in colour:</strong> the kit&#39;s boxes come in colours now (red, blue, sky, orange, pink, purple); each nest takes the box nearest its colour, recoloured to its exact colour, so the shading is cleaner than when every colour was made from the red box. The background is the kit&#39;s newer wood. The front row stays closed boxes in the white frame; waiting nests stay closed boxes.</li><li><strong>Sugar Drop art:</strong> the game screen uses the Sugar Drop prototype kit: wood background, a picture frame whose funnel curves in under it (the sand in the funnel follows its curved sides, so the funnel holds a little less sand), a conveyor with a half-clear holder under each slot and a green fill gauge, orange booster buttons with claw (Activate), shuffle and flower (Fan) pictures and a red badge, a settings button (opens the pause panel) and a white x2 button. Nests are flat boxes from the kit in their colour (the art is recoloured per colour) instead of 3D boxes; front nests have the kit&#39;s white frame, waiting nests stay lower and paler. The sand picture follows the frame&#39;s rounded inside: sand in its corners (round at the top, curving in toward the funnel at the bottom) is cut off at the start and falling sand cannot go there, so pictures that fill the frame (levels 5 and 9) lose a few grains there. The Level Editor shows the same: its frame is the kit&#39;s white rim on the light blue inside, its corners are rounded the same way and cannot be painted, the image converter leaves them empty, and saving a picture drops any sand there. The Fan still drops the ball cannon. Recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>New lose screens:</strong> made from the new UI kit (Lose Screen). When the conveyor is full, an <strong>Out of Space!</strong> board shows a broken heart and two revive buttons: <strong>Free</strong> (ad) and <strong>900</strong> coins. Either one closes the board and the ball cannon clears the belt into the nests (it does not use up the Fan booster), then play goes on; there are no ads or coins yet. The ✕ gives up: a <strong>Level N</strong> board shows the lives (four hearts and a blank one), the time to the next heart counting down from 30:00 and &quot;Level failed!&quot;; <strong>Try Again</strong> or its ✕ starts the level over (there are no lives yet, so they are only shown). The old &quot;Conveyor full!&quot; panel with the mascot is gone.</li><li><strong>New win screen:</strong> made from the new UI kit (Win Screen): a blue background, &quot;Level N&quot; over the &quot;AMAZING&quot; title, a pile of coins in a glow with turning rays, &quot;+40&quot; coins, confetti, an orange <strong>Claim x2</strong> button with an ad badge and 80 coins on its tab, and a green <strong>Continue</strong> button. Both buttons go on to the next level (no coins or ads yet). Colony Flow&#39;s &quot;Victory!&quot; letters, cheering ants and reward buttons are gone.</li><li><strong>x2 when the frame is empty:</strong> once all the sand has fallen off the picture frame, the rest of the level runs at x2 by itself and the x2 button hides, so it cannot be turned off. The next level starts at the speed the player had set.</li><li><strong>Nest numbers and waiting nests:</strong> every nest&#39;s number is white with a black stroke. Nests waiting behind the front row sit under a light, half-clear overlay, so their colour is paler and duller; it covers their number too (light grey with a grey stroke).</li><li><strong>Redrawn pictures:</strong> levels 1–4, 6, 7, 8 and 10 are drawn again from round shapes and curves instead of square cells, with an even outline (cherries with curved stems and a leaf, a wavy ice cream scoop on a criss-cross cone, a goldfish with curved fins, a pleated cupcake case, a balloon with curved panels and a woven basket, a cactus with a flower, a snail with a spiral shell, a penguin with a scarf). Same layout, colours and frame size. Cherries, Ice Cream and Penguin no longer have hand-set nests, so the game builds all eight levels&#39; nests (not re-checked with the test bot).</li><li><strong>Level 9 (Rocket):</strong> a new version from the Level Editor made for the 188-wide frame; it has no set nests, so the game builds them (rows order, seed 0).</li><li><strong>Frame holds a whole number of blocks:</strong> the sand frame is 188 grains wide (was 186; 870 px inside, was 864), so a full frame, 188 × 176 grains, is exactly 517 blocks and loses nothing to the trim. Pictures made for the old 186-wide frame fill the new one (their outer columns are doubled), so Little Owl and Rocket stay edge to edge with no sand cut. Recorded wins in the Level Editor need to be made again.</li><li><strong>Tighter pictures:</strong> the whole-block trim no longer leaves holes. When the frame has room, the missing grains are added next to the sand instead of cutting any (Rocket gains 41 grains); when the frame is full (Little Owl), only the picture&#39;s total remainder is removed, one grain at a time spread round its whole outer edge (32 grains; it used to lose 224 as scattered holes). Each colour&#39;s extra grains are handed to a neighbouring colour along their border instead of being removed. Hand-set nests that end up a block off are resized to fit. Little Owl has a new version from the Level Editor. Recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>Level Editor: recolour by drag:</strong> drop a Bank colour on a colour in Counts (or on the picture) to turn that whole colour into it; nests follow the new colour when it is not already in the picture.</li><li><strong>Level 5 (Little Owl):</strong> a new picture, a dog, with hand-set nests from the Level Editor; its lilac sand is purple (no recorded win yet).</li><li><strong>No gap from the exact-fit trim:</strong> the extra grains that make each colour a whole number of blocks are now taken spread evenly along the colour&#39;s outline. Before, they were taken in a run from the top left, which left a gap in the corner (level 9 lost 31 green grains there). Every picture changes by a few grains, so recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>Edited levels:</strong> level 9 (Rocket) has a new picture, a butterfly, with hand-set nests from the Level Editor (no recorded win yet; the test bot gets stuck on it); Ice Cream was edited too.</li><li><strong>Level Editor: move the picture in the frame:</strong> when making a sand picture from an image, arrow buttons (a cell at a time), a centre button and dragging the preview move the picture up, down, left or right; its sand never leaves the frame.</li><li><strong>Background zoomed in:</strong> the wooden planks are about 2.6 times wider (about 140 px, was 54), like the reference.</li><li><strong>Boosters unlock one by one:</strong> Activate at level 3, Shuffle at level 6, Fan at level 9 (the Fan was at level 5).</li><li><strong>Fan unlocks at level 5:</strong> in levels 1–4 the third booster is a grey button with a padlock; tapping it shows &quot;Unlocks at Level 5&quot;.</li><li><strong>Booster buttons like Sand Drop:</strong> green square buttons with new pictures (magnet for Activate, arrows for Shuffle, ball cannon for Fan), a red badge with the uses left and a green plus when none are left; Activate gets a yellow frame while it waits for a nest. The falling fan is unchanged.</li><li><strong>Fan animation:</strong> using the Fan dims the screen and drops the ball cannon into the middle; it sucks the conveyor&#39;s blocks into its mouth one by one, then shoots them one at a time, 0.2 s apart and 1.5 times their size in flight, into their nests. The game holds still until the last block is in its nest; the rules are unchanged.</li><li><strong>x2 speed:</strong> the x2 button always shows the speed the game runs at, and stopping Auto Play goes back to normal speed.</li><li><strong>Background:</strong> the page background is Food Hunt&#39;s light wooden planks (it was Colony Flow&#39;s picnic cloth).</li><li><strong>Boosters work:</strong> three boosters, 1 use each per level. <strong>Activate</strong> wakes a nest waiting behind the front row (tap the booster, then the nest), so ants fill it too. <strong>Shuffle</strong> makes the nests trade places. <strong>Fan</strong> blows every block on the conveyor into a nest of its colour, upper rows first. Activate uses the claw icon; the add-slot icon is gone. Without boosters the rules play out exactly as before (the test bot&#39;s results are unchanged).</li><li><strong>Win screen like Colony Flow&#39;s:</strong> &quot;Level N&quot; over &quot;Victory!&quot;, Colony Flow&#39;s two cheering ants (yellow and pink, put together from their <code>win_char</code> parts) jumping in turn either side of a pile of coins in the glow, and confetti raining down (paper strips that flip as they fall, white and yellow stars, shapes and curly streamers). The Next button is replaced by Colony Flow&#39;s two reward buttons, a yellow one with an ad badge (80 coins) and a green one (40); there are no coins yet, so both just go on to the next level.</li><li><strong>Ant paths:</strong> ants no longer all chase their block along the belt. Each leaves from its own spot on the nest and heads off its block by its own amount, from chasing it to cutting across to where they meet, so the paths vary. This changes the timing, so recorded wins in the Level Editor need to be made again (not re-checked with the test bot).</li><li><strong>Sand Drop layout:</strong> the screen is laid out like Sand Drop: Color Sort Puzzle. The picture frame is bigger and nearly as wide as the screen (inside 864 × 820 px, was 824 × 744), so sand cells are bigger (37 px, was 33.5); the boosters sit in a row under the level title instead of a tray at the bottom; the x2 button uses Colony Flow&#39;s speed button (grey off, green on) with its fast-forward icon; the funnel, conveyor (832 px wide, was 704) and nests moved down, and the nest columns are 172 px apart; the third nest row shows down to its number, as before. Recorded wins in the Level Editor need to be made again. The test bot still clears every built-in level.</li><li><strong>Nest rows:</strong> the nests waiting behind the front row sit 28 px lower, so they no longer touch the front nests&#39; white outline.</li><li><strong>Pause panel:</strong> the pause button opens a panel made from the team&#39;s settings art (<code>public/assets/settings</code>): board with a red close button, music, sound and vibration switches (remembered), green Restart and red Home buttons, and the level cheat underneath. Vibration buzzes on a filled nest, a win and a loss.</li><li><strong>Blue frame and conveyor:</strong> after the team&#39;s reference screen, the picture frame and the funnel have a white rim around a periwinkle inside, and the conveyor is slate blue with white rims (they were tan and brown). The page background is unchanged.</li><li><strong>Same sand scale in every level:</strong> the frame is always 22 cells tall, so sand cells and grains are the same size in every level; smaller pictures (Cherries, Ice Cream and others) now sit centred in the frame instead of being blown up. In the Level Editor, picture size (12–22) sets how big the picture is in the frame. Recorded editor wins need to be made again; the bot still clears the same levels as before.</li></ul><p><a href="https://tuandds.github.io/colony-flow-sand/demo/" target="_blank" rel="noreferrer">Play latest</a></p><h2 id="v1-0-1" tabindex="-1">v1.0.1 <a class="header-anchor" href="#v1-0-1" aria-label="Permalink to &quot;v1.0.1&quot;">​</a></h2><ul><li><strong>Edited levels:</strong> nine built-in levels were changed in the Level Editor (pictures; Cherries, Rocket and Penguin also got nests set by hand). Garden Snail, Rocket and Penguin have no recorded win yet, and the test bot gets stuck on them. The eyes of Goldfish, Little Owl, Garden Snail and Penguin use the outline colour (Little Owl: nest seed 5).</li><li><strong>Levels:</strong> 10 new original pictures (Cherries, Ice Cream, Goldfish, Cupcake, Little Owl, Hot Air Balloon, Cactus Pot, Garden Snail, Rocket, Penguin) with a dark outline and rising difficulty. Each one was cleared by a test bot when it was added; the old large levels 4 and 5 are gone.</li><li><strong>Level Editor</strong> (<code>/demo/editor.html</code>), laid out like the team&#39;s level editor template, with Editor and Organizer modes. Import an image to get a sand picture made grain by grain in the editor&#39;s sand colours, closest by eye (CIELAB), keeping small distinct details. Paint with brush, fill and replace tools. Nests are generated from a recorded winning play and checked by replaying it; you can also edit them by hand. The Level Bank has search, filters, version history and backups; the Organizer handles chapter sets, play, Auto Play and checks for a whole set, and CSV/JSON export. Levels are saved in the browser and played with <code>?custom=1</code>. See the <a href="/colony-flow-sand/docs/guide/level-editor">guide</a>.</li><li><strong>Editor pictures fill the frame:</strong> custom pictures cover the frame&#39;s whole inside (wider than the built-in square pictures), and the Sand Editor shows exactly that area, so a picture that touches the edge in the editor touches the frame in the game. The generator can fit the image or fill the frame.</li><li><strong>Win screen like Colony Flow:</strong> &quot;Victory!&quot; pops in letter by letter over glow and turning rays, and a big green Next button pulses (Colony Flow&#39;s win art, animated with tweens).</li><li><strong>Colour Bank like the template:</strong> an Active Palette per level (tap or drag colours in, keys 1–0, eraser), a Bank you can reorder, add to and edit (name, colour, delete) with long-press, and an option to build a picture from the Active Palette only.</li><li><strong>Colour Bank colours:</strong> the Bank adds the template&#39;s colours the game lacked, purples included, and drops colours that looked alike (24 colours); a Bank saved earlier is updated once, keeping your own colours.</li><li><strong>Funnel order:</strong> sand in the funnel now goes down the hole oldest first. Before, the hole always took the bottom row from the left, so newer sand falling into those cells jumped ahead while older sand lying further along waited (up to 8 s). Recorded wins in the Level Editor were made under the old rules: run Auto-generate nests again for those levels. The built-in levels still win with the test bot.</li><li><strong>Game levels in the Level Editor:</strong> the 10 built-in levels are in the Level Bank (chapter set &quot;Game&quot;), looking and playing exactly as in the game. When you save a change to one, the game plays the changed version: at once in the same browser, and on the dev server the editor also writes it to <code>src/game/level-edits.json</code> so it can be committed and published.</li><li><strong>Nest Editor drag and drop:</strong> drag a nest onto another to swap them, or onto a column&#39;s ＋ to move it there.</li><li><strong>Nest columns per level:</strong> a level can have 2 to 6 nest columns (default 4, as in every built-in level); the Nest Editor has a picker for it.</li><li><strong>Rules:</strong> the sand, funnel and particle randomness now comes from a generator seeded per level, and ants walk from a nest&#39;s front slot rather than its sliding position, so the same swipes always play out the same. The built-in levels were re-checked with the test bot; Rocket now uses seed 1.</li><li><strong>Funnel:</strong> the funnel is as wide as the sand frame, so sand falls straight into it from anywhere along the board; sand on its gentle walls slides toward the hole. Little Owl now uses nest seed 6.</li><li><strong>Conveyor capacity:</strong> the conveyor holds 30 blocks (was 24). The test bot still clears every level.</li><li><strong>Screen layout:</strong> the sand board is taller (inside 824 × 744 px, same width), so built-in pictures are bigger; the conveyor is slimmer with smaller blocks (32 px), and the nests sit lower so the third row shows about two thirds above the tray. Penguin got a new nest seed (6) so the test bot still clears every level. Level editor pictures made for the old frame are re-centred and need their nests generated again.</li><li><strong>Losing:</strong> the level is lost only when the conveyor is full and no block on it can go into a nest any more; before, a full belt with one more block waiting in the hole lost even while ants could still take blocks. The end panel now says &quot;No block on the belt fits a nest&quot;.</li><li><strong>Block sound:</strong> a new block landing on the belt now plays a short, soft cube sound (<code>cube_break_1</code>) instead of the long, loud box drop, which piled up into a shrill noise.</li><li><strong>Conveyor bar:</strong> the bar in the middle of the conveyor now fills with how full the belt is (green, yellow from 60 %, red from 85 %); before, the fill was drawn under the white bar and only the % showed.</li><li><strong>Nest numbers:</strong> nests waiting behind the front row show their number without the dark stroke: white on darker tiles, a darker shade of the nest colour on light ones.</li><li><strong>Nests:</strong> the nests now use Colony Flow&#39;s lidded nest box (<code>Box_v2_T</code> + <code>Box_v2_B</code>), with the white outline hugging its shape.</li></ul><p><a href="https://tuandds.github.io/colony-flow-sand/v1.0.1/demo/" target="_blank" rel="noreferrer">Play v1.0.1</a> · <a href="https://tuandds.github.io/colony-flow-sand/v1.0.1/docs/" target="_blank" rel="noreferrer">Docs v1.0.1</a></p><h2 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h2><ul><li><strong>Sand:</strong> swipe the picture to set sand free; loose sand falls, slides off slopes and past the picture edges, and leaves through the bottom of the board. Every colour fits whole blocks exactly, so no sand is left over.</li><li><strong>Funnel and hole:</strong> sand piles up in the funnel and trickles into the hole; a finished block waiting in the hole plugs it until it drops onto the conveyor.</li><li><strong>Conveyor:</strong> 24 slots; the bar in the middle shows how full it is, and overflowing it loses the level.</li><li><strong>Nests and ants:</strong> Colony Flow&#39;s 3D nests, ants and blocks; ants carry matching blocks home, full nests pop and the column slides up. Front-row nests have a white outline, queued nests are lower and paler.</li><li><strong>Levels:</strong> 10 levels; levels 1–5 use Colony Flow pictures. Levels 4 and 5 are very large and not yet winnable in practice (see <a href="./roadmap#known-issues">Known issues</a>).</li><li><strong>UI:</strong> settings with Resume, Restart and a cheat to jump to any level; x2 speed; boosters are shown but do nothing yet.</li><li><strong>Start-up:</strong> the game no longer waits forever if the web font is slow, shows an error instead of hanging, and shows the nests on the start screen.</li><li><strong>Game Design Document:</strong> overview, core loop, rules with the numbers from the code, roadmap and known issues.</li></ul><p><a href="https://tuandds.github.io/colony-flow-sand/v1.0.0/demo/" target="_blank" rel="noreferrer">Play v1.0.0</a> · <a href="https://tuandds.github.io/colony-flow-sand/v1.0.0/docs/" target="_blank" rel="noreferrer">Docs v1.0.0</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-10-27</td><td>GDD created</td></tr><tr><td>2026-10-27</td><td>Released v1.0.0</td></tr><tr><td>2026-10-28</td><td>Released v1.0.1</td></tr><tr><td>2026-11-03</td><td>Gameplay chapters rewritten in the core gameplay format: <a href="./core-gameplay">Core gameplay</a> (overview, then one table per screen zone) and <a href="./levels">Levels</a> replace Overview, Core loop and Rules &amp; mechanics</td></tr><tr><td>2026-11-03</td><td><a href="./user-flow-ui">User Flow &amp; UI</a> added: the wire flow and every screen, the prototype&#39;s (live) and those still to build for the Unity game (Home, More Coins, New Feature, Purchase Booster, Loading screen and transition, Tutorial, Medium &amp; Hard UI)</td></tr><tr><td>2026-11-03</td><td><a href="./booster">Booster</a> added: Activate, Shuffle and Fan with their states (Lock, Number, Add, Fade), pause and cancel rules, and the purchase popup for Unity</td></tr></tbody></table>',10))])}const y=s(d,[["render",u]]);export{v as __pageData,y as default};
